diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..c1374e85e
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,22 @@
+// Usage: node repro/check.js [path/to/typescript.js]   (default: built/local/typescript.js)
+// Prints how the checker displays `Test` for the report's code and exits 1 if it is not `{ prop1: "hello"; }`.
+const path = require("path");
+const tsPath = path.resolve(process.argv[2] || path.join(__dirname, "../built/local/typescript.js"));
+const ts = require(tsPath);
+const expected = `{ prop1: "hello"; }`;
+let failed = false;
+console.log("typescript", ts.version, "(" + tsPath + ")");
+for (const name of ["issue.ts", "workaround.ts"]) {
+    const file = path.join(__dirname, name);
+    const program = ts.createProgram([file], { strict: true, target: ts.ScriptTarget.ES2022, noEmit: true, types: [] });
+    const checker = program.getTypeChecker();
+    const sf = program.getSourceFile(file);
+    let test;
+    ts.forEachChild(sf, n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") test = checker.getTypeAtLocation(n.name); });
+    const shown = checker.typeToString(test, undefined, ts.TypeFormatFlags.NoTruncation);
+    const propType = checker.typeToString(checker.getTypeOfSymbol(checker.getPropertiesOfType(test)[0]));
+    const ok = shown === expected;
+    console.log(`${name}: Test = ${shown}   [Test.prop1 via getTypeOfSymbol = ${propType}]  ${ok ? "OK" : "WRONG (expected " + expected + ")"}`);
+    if (name === "issue.ts" && !ok) failed = true;
+}
+process.exit(failed ? 1 : 0);
diff --git a/repro/issue.ts b/repro/issue.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/issue.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
diff --git a/repro/workaround.ts b/repro/workaround.ts
new file mode 100644
index 000000000..f8f04aa6d
--- /dev/null
+++ b/repro/workaround.ts
@@ -0,0 +1,24 @@
+// Same as issue.ts, but the assertion is on its own line (the reporter's workaround).
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const strWrapper = stringWrapper() as Wrapper<"hello">;
+
+const value = objWrapper({
+    prop1: strWrapper
+});
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
